fn solve(n: i8) -> Vec<i8> {
    // Number of complete 7-day weeks
    let weeks = n / 7;
    // Remaining days beyond the complete weeks
    let r = n % 7;

    // Minimum extra days off in the partial week:
    // If r ≤ 5, you can avoid weekends entirely => 0 days off.
    // If r > 5, at least (r − 5) of those days must include weekend days.
    let min_add = if r > 5 { r - 5 } else { 0 };

    // Maximum extra days off in the partial week:
    // You can include at most the two weekend days, and no more than r days total.
    let max_add = if r < 2 { r } else { 2 };

    // Total days off = 2 per complete week + extras from the partial week
    let min_off = 2 * weeks + min_add;
    let max_off = 2 * weeks + max_add;

    vec![min_off, max_off]
}

fn main() {
    let tests = [1, 5, 6, 7, 10, 14, 15];
    for &n in &tests {
        let ans = solve(n);
        println!("n = {:2} -> [min, max] = {:?}", n, ans);
    }
}